insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('NP', 'default', 'Nepal reference chart of accounts', '{}'::jsonb, true, 'companies', array['NP-NFRS-IS', 'NP-NFRS-SFP']::text[], null, 'There is no legal chart of accounts in Nepal. The Companies Act requires financial statements prepared in accordance with the accounting standards in force; the Accounting Standards Board Nepal issues them — the Nepal Financial Reporting Standards 2024 for public-interest entities and the NFRS for SMEs, mandatory from 16 July 2024 for entities without public accountability (IFRS Foundation jurisdiction profile). Nepal has no statutory layout of the statements. This chart is original: four digits, blocked so that each range reaches one line of the statements below, with the accounts a Nepalese company actually keeps — VAT output and input kept apart, import VAT owed at customs clearance, the net VAT due to or from the Inland Revenue Department after a return, tax deducted at source, remuneration tax and provident fund contributions payable.', 'ifrs-profile')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

