insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('NP', 'NP-P-13', 'Purchase, standard rate 13 %', '{}'::jsonb, 'A taxable purchase at the standard rate whose input tax is deducted', 'percent', 13, 'purchase', 'domestic', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 17(1) — a registered person may deduct the tax paid or to be paid on importing or receiving goods or services related to its own taxable transaction from the tax it collected; s. 17(6) — the deduction is granted only on the documents prescribed; s. 7(1) — thirteen percent. Deducted in full when the purchase serves taxable or zero-rated transactions only; s. 17(3) apportions the deduction when it also serves exempt ones, which this code does not do.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-P-13-ND', 'Purchase, standard rate 13 %, input tax not deductible', '{}'::jsonb, 'A purchase whose input tax the Rules block or only partly allow — the goods of s. 17(2)', 'percent', 13, 'purchase', 'domestic', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 17(2) — the Rules may allow no deduction, or a partial one, for prescribed goods that can be used for commercial or personal purposes. The Rules that list those goods could not be read; the code is here for the purchase whose input tax the user''s accountant has found blocked or only partly deductible, and the tax charged follows the expense to account 6530 and reaches no box.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-P-EX', 'Purchase, exempt', '{}'::jsonb, 'An exempt supply bought for the business', 'percent', 0, 'purchase', 'exempt', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 5(3) — an exempt transaction bears no tax, so a purchase of Schedule 1 goods or services carries no input tax; the return has no row for it.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-P-IMP', 'Import of goods, VAT paid at customs clearance', '{}'::jsonb, 'VAT charged on a taxable import, paid at customs clearance and claimed as input tax', 'percent', 13, 'purchase', 'import', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 5(1)(b) — value-added tax is levied on goods imported into Nepal; s. 17(1) — the importer deducts the tax paid on importing. Posted to 2125 (import VAT payable at customs clearance) against the deduction in the return, so that the account holds what customs collects until the invoice of the clearing agent or the customs receipt settles it.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-P-RC-SVC', 'Service from outside Nepal, reverse-charged and deductible', '{}'::jsonb, 'A service supplied from outside Nepal, taxed to the recipient who may deduct the tax', 'percent', 13, 'purchase', 'foreign_services_received', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 8(2) — a person, registered or not, who acquires a service from a person outside Nepal assesses and realizes the tax on the taxable value; s. 17(5b) — the taxpayer may deduct the tax paid under s. 8(2). The output tax is declared in box 1R and the credit in box 2R, so the net effect for a fully taxable buyer is nil.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-S-13', 'Sale, standard rate 13 %', '{}'::jsonb, 'The flat rate on a taxable supply of goods or services made in Nepal', 'percent', 13, 'sale', 'domestic', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 5(1)(a) — value-added tax is levied on goods or services supplied within Nepal, on the value of each taxable transaction (s. 5(2)); s. 7(1) — the rate of tax is the flat rate of thirteen percent (a flat rate set by the Financial Act, 2018 in the text read); s. 6(2) — the time of supply. Every transaction that Schedule 1 does not exempt and Schedule 2 does not zero-rate is taxed at this rate.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply that Schedule 1 exempts: the essentials of the secondary guides — basic agricultural products, health, education', 'percent', 0, 'sale', 'exempt', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 5(3) — tax is not levied on the transaction of the goods or services referred to in Schedule 1, and the tax paid on what was bought for it cannot be deducted under s. 17 nor refunded under s. 24; s. 10(3) — a person who carries on only such exempt transactions need not register. Schedule 1 could not be read: basic agricultural products, health, education and similar essentials are what the secondary guides list, and the item list is a gap.', 'E', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('NP', 'NP-S-Z-EXP', 'Sale, zero-rated (Schedule 2, exports)', '{}'::jsonb, 'Goods and services taxed at the zero rate of Schedule 2, chiefly exports', 'percent', 0, 'sale', 'export', date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 7(2) — the tax on the goods or services set out in Schedule 2 is levied at the rate of zero percent; a zero-rated transaction stays a taxable one, so the registered person keeps the deduction of s. 17 on what it bought to make it. Schedule 2 could not be read: exports of goods and services are its principal content according to the commentary on the Act (see the README), and the item list is a gap.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

