insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('NP', 'NP-VAT-RETURN', 'Monthly value-added tax return', array['month']::declaration_period[], 'month'::declaration_period, date '2021-09-29', null, 'Value-Added Tax Act, 2052, s. 18(1) — every taxpayer assesses the tax payable each month and submits the return, in the form prescribed, in person, by registered post or electronically, within twenty-five days of the completion of that month, whether or not a taxable transaction took place; s. 18(2) — prescribed taxpayers may file for a longer or shorter period; s. 19(1) — the tax of a period is paid within twenty-five days of its completion; s. 17 — the deduction; s. 8(2) — the service acquired from outside Nepal. The form is filed electronically and was not readable from the machine this pack was written on: the rows below are this pack''s own, grouped under the figures the Act names, and the gap is recorded in this pack''s README.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Value-Added Tax Act, 2052, ss. 18(1) and 19(1) — within twenty-five days of the completion of the month. Nepal counts the month in the Bikram Sambat calendar (Baisakh to Chaitra) while this pack''s periods are Gregorian months, so day 25 of the following Gregorian month is an approximation recorded in the README. A late payment bears an additional fee of ten percent a year (s. 19(2)); it is not modelled.', 'vat-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

