  ('NP', 'NP-VAT-RETURN', '3', 'base', 'Imports of goods — value', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value-Added Tax Act, 2052, s. 5(1)(b) — the value of taxable imports. A reporting row of this pack.', 'vat-act'),
