  ('NP-NFRS-IS', 'NP', 'default', 'Statement of profit or loss', 'income_statement', 'NFRS', date '2014-01-01', null, 'The Companies Act requires financial statements prepared in accordance with the accounting standards in force, which the Accounting Standards Board Nepal issues: the NFRS for SMEs, mandatory from 16 July 2024 for entities without public accountability, and the NFRS 2024 for public-interest entities (IFRS Foundation jurisdiction profile). Nepal has no statutory format for the statements, so these lines are an original presentation by nature of expense that follows IAS 1 / section 5 of the NFRS for SMEs (statement of profit or loss).', 'ifrs-profile', null, null, '{}'::jsonb),
  ('NP-NFRS-SFP', 'NP', 'default', 'Statement of financial position', 'balance_sheet', 'NFRS', date '2014-01-01', null, 'The Companies Act requires financial statements prepared in accordance with the accounting standards in force, which the Accounting Standards Board Nepal issues: the NFRS for SMEs, mandatory from 16 July 2024 for entities without public accountability, and the NFRS 2024 for public-interest entities (IFRS Foundation jurisdiction profile). Nepal has no statutory format for the statements, so these lines are an original presentation by nature of expense that follows IAS 1 / section 4 of the NFRS for SMEs (statement of financial position).', 'ifrs-profile', 'combined', 'Result of the current financial year', '{}'::jsonb)
