update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value-Added Tax Act, 2052, s. 14(1) — every registered person is required to issue an invoice for a taxable transaction in the form the Rules prescribe. The Rules (Value Added Tax Rules, 2053) fix the particulars and the serial number of the invoice; they could not be read, so the pack declares a sequential number and not a gapless one, and records the gap in its README. Section 14A lets a taxpayer issue an electronic invoice with the Department''s approval and lets the Department order named taxpayers to link their billing software to its central invoice monitoring system.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value-Added Tax Act, 2052, s. 6(2) — the time of supply is the earliest of the issue of the invoice, the receipt of the goods by the recipient (goods) or the rendering of the service (services), and the receipt of consideration by the supplier; s. 6(3) — continuous telecommunication services at the invoice, instalment contracts at each payment. Ekwo''s closed vocabulary has a two-way earliest-of; `earliest_of_delivery_or_payment` is the nearest value, and the gap — an invoice issued ahead of both delivery and payment, which fixes the time of supply in Nepal — is recorded in the README.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Value-Added Tax Act, 2052, s. 14A — a taxpayer may issue an electronic invoice with the Department''s prior approval, and the Department may by notice order named taxpayers to issue it compulsorily and link it to its central invoice and billing monitoring system (CBMS). That is an approval and a link to a tax authority''s system, not an exchange of a structured invoice between businesses: Nepal has no Peppol authority and no published profile, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. If the Department publishes a profile, this field is where it goes.',
  einvoice_source_key           = 'vat-act',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'july'
 where country = 'NP';
